contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Run tries to call initialize with arbitrary inputs and then asserts the general invariant:
    // Either the call reverted and the pool remained uninitialized (initialized() == false),
    // or the call succeeded and then initialized() == true and public getters match the inputs.
    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public payable {
        // We must ensure we observe the state before and after the call.
        // Read initial initialized flag (should be false for a fresh pool but we don't require it).
        bool beforeInitialized = c.initialized();

        bool reverted;
        // Call initialize on c. It may revert (e.g., AlreadyInitialized or FeeRateTooHigh).
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read relevant public state after the call
        bool afterInitialized = c.initialized();
        address afterBaseToken = c.baseToken();
        address afterNft = c.nft();
        uint128 afterVBase = c.virtualBaseTokenReserves();
        uint128 afterVNft = c.virtualNftReserves();
        uint56 afterChangeFee = c.changeFee();
        uint16 afterFeeRate = c.feeRate();
        bytes32 afterMerkle = c.merkleRoot();
        bool afterUseOracle = c.useStolenNftOracle();
        bool afterPayRoyalties = c.payRoyalties();

        // The general rule:
        // - If the call reverted then the contract must not have become initialized as a result
        //   (i.e., afterInitialized must equal beforeInitialized or remain false). We express a
        //   conservative property: if reverted then afterInitialized == beforeInitialized AND
        //   no observed public parameter should equal the new inputs unless they already did.
        // - If the call succeeded then afterInitialized must be true and the public getters must
        //   reflect the inputs passed to initialize.
        // We encode this in a single assert expression.
        assert(
            (
                reverted
                ? (
                    // nothing changed: initialized unchanged AND if it was false before it remains false,
                    // and if it was true before then we conservatively allow any change (since spec allows AlreadyInitialized revert),
                    // but to be strict: require initialized remained same and no public fields match the new inputs unless they matched before.
                    afterInitialized == beforeInitialized
                    && (
                        // if beforeInitialized was false then none of the fields should have become equal to the new inputs
                        (beforeInitialized == false)
                            ? (
                                !(afterBaseToken == _baseToken && afterBaseToken != c.baseToken()) &&
                                !(afterNft == _nft && afterNft != c.nft()) &&
                                !(afterVBase == _virtualBaseTokenReserves && afterVBase != c.virtualBaseTokenReserves()) &&
                                !(afterVNft == _virtualNftReserves && afterVNft != c.virtualNftReserves())
                            )
                            : true
                    )
                )
                : (
                    // succeeded: must be initialized and public getters equal inputs
                    afterInitialized == true
                    && afterBaseToken == _baseToken
                    && afterNft == _nft
                    && afterVBase == _virtualBaseTokenReserves
                    && afterVNft == _virtualNftReserves
                    && afterChangeFee == _changeFee
                    && afterFeeRate == _feeRate
                    && afterMerkle == _merkleRoot
                    && afterUseOracle == _useStolenNftOracle
                    && afterPayRoyalties == _payRoyalties
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // params: we pass tokenIds and tokenWeights and a MerkleMultiProof (as memory arrays encoded via dynamic params)
    // Also pass an amount of ETH to forward (amount) so tests can try ETH and token variants.
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofProof,
        bool[] calldata proofFlags,
        uint256 baseTokenEtherValue
    ) public payable {
        // must have enough balance to forward ETH if requested
        require(address(this).balance >= baseTokenEtherValue);

        // Preconditions for sensible inputs: arrays lengths must match and non-empty tokenIds
        require(tokenIds.length == tokenWeights.length);
        require(tokenIds.length > 0);

        // Build MerkleMultiProof struct in memory for the call
        C.MerkleMultiProof memory multiProof = C.MerkleMultiProof({ proof: new bytes32[](proofProof.length), flags: new bool[](proofFlags.length) });
        for (uint i = 0; i < proofProof.length; i++) multiProof.proof[i] = proofProof[i];
        for (uint i = 0; i < proofFlags.length; i++) multiProof.flags[i] = proofFlags[i];

        // Read virtualNftReserves before
        uint256 beforeVN = c.virtualNftReserves();

        // Compute weight sum (mirror of contract's sum) to avoid calling internal funcs
        uint256 weightSum = 0;
        for (uint i = 0; i < tokenWeights.length; i++) {
            weightSum += tokenWeights[i];
        }

        // Try performing buy; it may revert. We capture revert flag.
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: baseTokenEtherValue}(tokenIds, tokenWeights, multiProof) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Read virtualNftReserves after
        uint256 afterVN = c.virtualNftReserves();

        // We also observe at least one token's ownership change if the call succeeded: before the pool owned the token (fresh pools often have tokens), but we cannot rely on that.
        // Instead we use availableForFlashLoan(token, id) which returns true iff ownerOf(id) == address(this pool).
        // We'll check that if buy succeeded then virtualNftReserves decreased by weightSum.
        // If buy reverted then virtualNftReserves must be unchanged.

        // Final general rule asserted:
        // - If reverted: pool's virtualNftReserves unchanged.
        // - If succeeded: afterVN + 0 == beforeVN - weightSum (i.e., decreased by weightSum), and netInputAmount equals the sum computed by buyQuote for that output (consistency of quote): netInputAmount >= 0.
        // express as single assert
        assert(
            reverted
                ? (afterVN == beforeVN)
                : (beforeVN == afterVN + weightSum)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Test deposits: pass nft tokenIds, and an ETH amount to forward (baseTokenEtherValue).
    // We require at least one tokenId and that arrays are non-empty and short to simplify reasoning.
    function run(uint256[] calldata tokenIds, uint256 baseTokenEtherValue) public payable {
        require(tokenIds.length > 0 && tokenIds.length <= 8, "bad tokenIds length");
        // ensure this contract has enough balance to forward ETH if testing native-ETH pool deposit
        require(address(this).balance >= baseTokenEtherValue, "insufficient test balance");

        // Observe base token address and nft address before
        address baseToken = c.baseToken();
        address nftAddr = c.nft();

        // Read pool's NFT balance for the nft contract before
        uint256 beforeNftBalance = ERC721(nftAddr).balanceOf(address(c));
        uint256 beforePoolEth = address(c).balance;

        // Try deposit; capture revert flag
        bool reverted;
        try c.deposit{value: baseTokenEtherValue}(tokenIds, 0) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterNftBalance = ERC721(nftAddr).balanceOf(address(c));
        uint256 afterPoolEth = address(c).balance;

        // Rule: If deposit reverted then balances unchanged; else NFT balance increased by tokenIds.length
        // and ETH held by pool increased by baseTokenEtherValue iff baseToken == address(0)
        assert(
            reverted
                ? (afterNftBalance == beforeNftBalance && afterPoolEth == beforePoolEth)
                : (afterNftBalance == beforeNftBalance + tokenIds.length && (baseToken == address(0) ? (afterPoolEth == beforePoolEth + baseTokenEtherValue) : (afterPoolEth == beforePoolEth)))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Test the change() behavior: provide input and output token id arrays and weights, and forward optional ETH amount.
    function run(
        uint256[] calldata inputTokenIds,
        uint256[] calldata inputTokenWeights,
        uint256[] calldata outputTokenIds,
        uint256[] calldata outputTokenWeights,
        uint256 ethToSend
    ) public payable {
        // keep arrays reasonably small for analysis and avoid excessive gas
        require(inputTokenIds.length <= 8 && outputTokenIds.length <= 8, "too many ids");
        require(inputTokenIds.length == inputTokenWeights.length && outputTokenIds.length == outputTokenWeights.length, "len mismatch");
        // ensure the test contract has funds to forward if needed
        require(address(this).balance >= ethToSend, "insufficient balance");

        // Observe NFT contract and base token address
        address nftAddr = c.nft();
        address baseToken = c.baseToken();

        // Snapshot balances and ownership evidence before the call
        uint256 beforePoolNftBalance = 0;
        if (nftAddr != address(0)) {
            beforePoolNftBalance = ERC721(nftAddr).balanceOf(address(c));
        }
        uint256 beforePoolEth = address(c).balance;

        // Call change and capture whether it reverted
        bool reverted;
        try c.change{value: ethToSend}(
            inputTokenIds,
            inputTokenWeights,
            C.MerkleMultiProof(new bytes32[](0), new bool[](0)),
            new IStolenNftOracle.Message[](0),
            outputTokenIds,
            outputTokenWeights,
            C.MerkleMultiProof(new bytes32[](0), new bool[](0))
        ) returns (uint256 feeAmount, uint256 protocolFeeAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Snapshot after
        uint256 afterPoolNftBalance = 0;
        if (nftAddr != address(0)) {
            afterPoolNftBalance = ERC721(nftAddr).balanceOf(address(c));
        }
        uint256 afterPoolEth = address(c).balance;

        // Compute weight sums (purely from inputs, safe in solidity since lengths bounded)
        uint256 inputSum = 0;
        for (uint256 i = 0; i < inputTokenWeights.length; i++) {
            inputSum += inputTokenWeights[i];
        }
        uint256 outputSum = 0;
        for (uint256 i = 0; i < outputTokenWeights.length; i++) {
            outputSum += outputTokenWeights[i];
        }

        // General rule asserted:
        // If change reverted then observable pool NFT and ETH balances unchanged.
        // Otherwise (succeeded): inputWeightSum >= outputWeightSum and pool NFT balance increases by (inputTokenIds.length - outputTokenIds.length)
        // and pool ETH doesn't unexpectedly change except for fees: at most it increases by msg.value forwarded (ethToSend) and decreases by returned excess.
        // We express a conservative observable rule: on success inputSum >= outputSum and NFT balance delta equals inputCount - outputCount.
        assert(
            reverted
                ? (afterPoolNftBalance == beforePoolNftBalance && afterPoolEth == beforePoolEth)
                : (inputSum >= outputSum && afterPoolNftBalance == beforePoolNftBalance + (inputTokenIds.length - outputTokenIds.length))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
