        address nftAddr = c.nft();

        // observe before-state
        uint256 beforePoolNftBalance = 0;
        if (nftAddr != address(0)) {
            beforePoolNftBalance = ERC721(nftAddr).balanceOf(address(c));
        }
        uint256 beforePoolEth = address(c).balance;

        // Make the state-changing call as a top-level statement and capture revert via try/catch
        bool reverted;
        uint256 feeOut;
        uint256 protocolFeeOut;
        try c.change{value: ethToSend}(
            inputTokenIds,
            inputTokenWeights,
            C.MerkleMultiProof(new bytes32[](0), new bool[](0)),
            new IStolenNftOracle.Message[](0),
            outputTokenIds,
            outputTokenWeights,
            C.MerkleMultiProof(new bytes32[](0), new bool[](0))
        ) returns (uint256 _feeOut, uint256 _protocolFeeOut) {
            reverted = false;
            feeOut = _feeOut;
            protocolFeeOut = _protocolFeeOut;
        } catch {
            reverted = true;
        }

        // observe after-state
        uint256 afterPoolNftBalance = 0;
        if (nftAddr != address(0)) {
            afterPoolNftBalance = ERC721(nftAddr).balanceOf(address(c));
        }
        uint256 afterPoolEth = address(c).balance;

        // compute input/output weight sums (purely local)
        uint256 inputSum = 0;
        for (uint256 i = 0; i < inputTokenWeights.length; i++) {
            inputSum += inputTokenWeights[i];
        }
        uint256 outputSum = 0;
        for (uint256 i = 0; i < outputTokenWeights.length; i++) {
            outputSum += outputTokenWeights[i];
        }

        // General rule (single assert):
        // - If reverted: observable NFT and ETH balances of pool unchanged.
        // - Else (succeeded): pool NFT balance delta == inputCount - outputCount.
        //   (We conservatively do not try to pin exact ETH delta because fees/royalties depend on internal state;
        //    instead we require ETH changed by at most the forwarded ethToSend plus any non-negative received fees: here we only assert NFT relation on success.)
        assert(
            reverted
                ? (afterPoolNftBalance == beforePoolNftBalance && afterPoolEth == beforePoolEth)
                : (afterPoolNftBalance == beforePoolNftBalance + (inputTokenIds.length - outputTokenIds.length))
        );
    }

