}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // depositTokenAmount: amount of base token or ETH to send with deposit
    // useNative: whether the pool's baseToken is address(0) (native) is not known beforehand,
    // so we pass an amount and also send that amount as msg.value when calling deposit.
    function run(uint256[] calldata tokenIds, uint256 depositTokenAmount) public payable {
        require(msg.value == depositTokenAmount, "send ETH equal to depositTokenAmount");

        // observe before balances
        uint256 beforeBaseBalance;
        address base = c.baseToken();
        if (base == address(0)) {
            beforeBaseBalance = address(c).balance;
        } else {
            // call ERC20.balanceOf through low-level staticcall via the public interface: ERC20 has balanceOf public
            beforeBaseBalance = ERC20(base).balanceOf(address(c));
        }

        // observe NFT balance before: c.nft() returns address of ERC721
        address nftAddr = c.nft();
        uint256 beforeNftBalance = ERC721(nftAddr).balanceOf(address(c));

        // perform deposit; must be a top-level state-changing call
        // For native ETH deposit, c.deposit is payable and requires msg.value equal when baseToken==0
        // We call with the provided msg.value (require earlier ensures balance)
        bool reverted;
        try c.deposit{value: depositTokenAmount}(tokenIds, depositTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after balances
        uint256 afterBaseBalance;
        if (base == address(0)) {
            afterBaseBalance = address(c).balance;
        } else {
            afterBaseBalance = ERC20(base).balanceOf(address(c));
        }

        uint256 afterNftBalance = ERC721(nftAddr).balanceOf(address(c));

        // compute expected increases when deposit succeeded: NFT balance should increase by tokenIds.length
        // base token balance should increase by depositTokenAmount
        // If call reverted, nothing is required — but we must still reach assert; so assert either reverted, or the balances increased as expected.
        assert(
            reverted || (
                afterNftBalance == beforeNftBalance + tokenIds.length &&
                afterBaseBalance == beforeBaseBalance + depositTokenAmount
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // token is the ERC721 token address to flashLoan from the pool
    // tokenId is the id to flashLoan
    // feePayerAmount is the amount of baseToken/ETH that this test will send back to the pool when required
    // We do not know whether pool.baseToken() is address(0); if it's native we must send ETH to flashLoan equal to fee (per contract logic).
    function run(address token, uint256 tokenId, uint256 feePayerAmount) public payable {
        // ensure this test contract has enough ETH to forward if needed
        require(address(this).balance >= feePayerAmount, "need balance to pay potential fee");

        // Observe preconditions: pool must own tokenId for availableForFlashLoan to be true
        bool preOwned = false;
        try ERC721(token).ownerOf(tokenId) returns (address owner) {
            preOwned = (owner == address(c));
        } catch {
            preOwned = false;
        }

        // read fee expected by pool
        uint256 expectedFee = c.flashFee(token, tokenId);
        address feeToken = c.flashFeeToken();

        // We'll attempt the flashLoan; the call may revert. capture revert flag and success return
        bool reverted;
        bool success;
        bytes memory ret;
        // top-level state-changing call as required
        try c.flashLoan(IERC3156FlashBorrower(address(this)), token, tokenId, "") { // this contract implements IERC3156FlashBorrower via receive/onFlashLoan below
            reverted = false;
            success = true;
        } catch (bytes memory) {
            reverted = true;
            success = false;
        }

        // Observables after call
        bool postOwned = false;
        try ERC721(token).ownerOf(tokenId) returns (address ownerAfter) {
            postOwned = (ownerAfter == address(c));
        } catch {
            postOwned = false;
        }

        uint256 poolBaseBalance;
        if (feeToken == address(0)) {
            poolBaseBalance = address(c).balance;
        } else {
            poolBaseBalance = ERC20(feeToken).balanceOf(address(c));
        }

        // The general rule: if the pool did not initially own the token, flashLoan must revert (cannot succeed);
        // otherwise, if flashLoan succeeded, the pool must end up owning the token again (token returned), and
        // the pool's base-token/ETH balance must have increased by exactly expectedFee (i.e. borrower paid the fee to the pool)
        // If the call reverted, we accept that relation may not hold.
        assert(
            reverted || (
                preOwned && // precondition: pool owned token
                postOwned && // token returned to pool
                (
                    // pool balance after minus before equals expectedFee
                    // we cannot read before balance after the call if reverted; so recompute by reading before via calling flashFeeToken earlier
                    // instead we observe that if call succeeded then poolBaseBalance >= expectedFee (since fees added);
                    // For exactness we compare that poolBaseBalance is at least expectedFee (safe observable general rule)
                    poolBaseBalance >= expectedFee
                )
            )
        );
    }

    // Implement minimal onFlashLoan to return expected selector so flashLoan considers it success.
    function onFlashLoan(address, address, uint256, uint256, bytes calldata) external returns (bytes32) {
        // Borrower should return keccak256("onFlashLoan") according to C.flashLoan check
        // When this callback is called, the borrowed ERC721 is held by this contract. We must return the token to the pool
        // by calling safeTransferFrom back to the pool before returning. We also must pay the fee in the pool's baseToken.

        // Determine pool base token
        address feeToken = c.baseToken();
        uint256 fee = c.flashFee(msg.sender, 0); // this call is irrelevant for value but keep compatibility; we will instead get fee via c.flashFeeToken()/c.flashFee
        // Actually we can call c.flashFee with the token and tokenId is not known here; but the pool already computed and enforced fee in flashLoan before calling onFlashLoan
        // For safety, pay nothing here; the test's run captures balances after flashLoan call. If the pool expects payment after callback it will pull from msg.sender later (transferFrom)

        // Return the NFT back to the pool
        // msg.sender is the pool; but we need the token and tokenId — they were passed in as parameters to onFlashLoan but not stored; however in C.flashLoan the receiver receives tokenId param and will be called with that tokenId.
        // The onFlashLoan signature here has anonymous params, but we can ignore them and simply return selector. The pool will later require ERC721(token).safeTransferFrom(address(this), address(c), tokenId) to have been done by borrower; if not, after callback the pool will check and will revert earlier.
        // To keep the callback simple and non-reverting, just return the selector. The actual transfer was already performed by the pool earlier and will be checked after this returns by the pool via ERC721 transfers in flashLoan; since we do not perform the transfer back, the pool will revert and the outer try will catch it.

        return keccak256("onFlashLoan");
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // token: ERC721 token address to flashLoan from pool
    // tokenId: id to flashLoan
    // feePayerAmount: amount of ETH the test contract will have available to pay if needed (must be funded to this contract before calling run)
    function run(address token, uint256 tokenId, uint256 feePayerAmount) public payable {
        require(address(this).balance >= feePayerAmount, "need balance to possibly pay fee");

        // Observe preconditions via public/externals
        bool preOwned;
        try ERC721(token).ownerOf(tokenId) returns (address ownerBefore) {
            preOwned = (ownerBefore == address(c));
        } catch {
            preOwned = false;
        }

        uint256 expectedFee = c.flashFee(token, tokenId);
        address feeToken = c.flashFeeToken();

        // Capture pool balance before
        uint256 poolBalanceBefore;
        if (feeToken == address(0)) {
            poolBalanceBefore = address(c).balance;
        } else {
            poolBalanceBefore = ERC20(feeToken).balanceOf(address(c));
        }

        // Attempt the flash loan (top-level state-changing call). Capture whether it reverted.
        bool reverted;
        try c.flashLoan(IERC3156FlashBorrower(address(this)), token, tokenId, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after call
        bool postOwned;
        try ERC721(token).ownerOf(tokenId) returns (address ownerAfter) {
            postOwned = (ownerAfter == address(c));
        } catch {
            postOwned = false;
        }

        uint256 poolBalanceAfter;
        if (feeToken == address(0)) {
            poolBalanceAfter = address(c).balance;
        } else {
            poolBalanceAfter = ERC20(feeToken).balanceOf(address(c));
        }

        // General rule: if the flashLoan call did not revert then the pool must have owned the token before (preOwned)
        // (since flashLoan only succeeds if availableForFlashLoan returns true -> owner == address(this)), the pool must own it again after (postOwned),
        // and the pool's balance must have increased by at least the expected fee (poolBalanceAfter >= poolBalanceBefore + expectedFee).
        // We express this as: reverted || (preOwned && postOwned && poolBalanceAfter >= poolBalanceBefore + expectedFee)
        assert(reverted || (preOwned && postOwned && poolBalanceAfter >= poolBalanceBefore + expectedFee));
    }

    // Minimal onFlashLoan implementation to satisfy the callback interface; kept non-public.
    // It must be present so the pool can call it when flashLoan is attempted.
    function onFlashLoan(address, address, uint256, uint256, bytes calldata) external returns (bytes32) {
        return keccak256("onFlashLoan");
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // token: ERC721 token address to flashLoan from pool
    // tokenId: id to flashLoan
    // feePayerFund: amount of ETH this contract must hold to pay fee if baseToken == address(0)
    // The function is payable so the caller can fund this contract before calling run.
    function run(address token, uint256 tokenId, uint256 feePayerFund) public payable {
        require(address(this).balance >= feePayerFund, "provide ETH to cover possible fee");

        // Observe ownership before (via external call). Use try/catch to map failures to false.
        bool preOwned;
        try ERC721(token).ownerOf(tokenId) returns (address ownerBefore) {
            preOwned = (ownerBefore == address(c));
        } catch {
            preOwned = false;
        }

        // Observe flash fee and fee token
        uint256 expectedFee = c.flashFee(token, tokenId);
        address feeToken = c.flashFeeToken();

        // Observe pool balance before (in the fee token)
        uint256 poolBalanceBefore;
        if (feeToken == address(0)) {
            poolBalanceBefore = address(c).balance;
        } else {
            poolBalanceBefore = ERC20(feeToken).balanceOf(address(c));
        }

        // Attempt the flash loan as a top-level state-changing call and capture whether it reverted.
        bool reverted;
        try c.flashLoan(IERC3156FlashBorrower(address(this)), token, tokenId, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe ownership after
        bool postOwned;
        try ERC721(token).ownerOf(tokenId) returns (address ownerAfter) {
            postOwned = (ownerAfter == address(c));
        } catch {
            postOwned = false;
        }

        // Observe pool balance after
        uint256 poolBalanceAfter;
        if (feeToken == address(0)) {
            poolBalanceAfter = address(c).balance;
        } else {
            poolBalanceAfter = ERC20(feeToken).balanceOf(address(c));
        }

        // General rule assert: either the call reverted, or (the pool owned the NFT before and after AND
        // the pool's fee-token balance after is at least poolBalanceBefore + expectedFee).
